app.use(helmet({
  contentSecurityPolicy: NODE_ENV !== 'development', // Disable in dev for CORS
  crossOriginEmbedderPolicy: NODE_ENV === 'production'
}));
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Health check (without sensitive info)
app.get('/health', async (req, res) => {
  res.json({ 
    status: 'ok',
    uptime: process.uptime(),
    timestamp: Date.now()
  });
});

// Dynamic user data from environment or database
app.get('/users', (req, res) => {
  const users = process.env.USERS 
    ? JSON.parse(process.env.USERS) 
    : [];
  res.json(users);
});

// Graceful shutdown
const server = app.listen(PORT, HOST, () => {
  if (NODE_ENV !== 'test') {
    console.log(`Server running on http://${HOST}:${PORT} [${NODE_ENV}]`);
  }
});

process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('\nSIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;
